#nullable enable

class C
{
    C M0(object obj) => this;

    void M1(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is (_)
            ? x.ToString() // 1
            : y.ToString(); // unreachable
    }

    void M2(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is var z
            ? x.ToString() // 2
            : y.ToString(); // unreachable
    }

    void M3(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is { }
            ? x.ToString()
            : y.ToString(); // 3
    }

    void M4(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is { } c1
            ? x.ToString()
            : y.ToString(); // 4
    }

    void M5(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is C c1
            ? x.ToString()
            : y.ToString(); // 5
    }

    void M6(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is not null
            ? x.ToString()
            : y.ToString(); // 6
    }

    void M7(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is not C
            ? x.ToString() // 7
            : y.ToString();
    }

    void M8(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is null
            ? x.ToString() // 8
            : y.ToString();
    }
}

